alter table public.novacart_knowledge add column if not exists embedding_mistral extensions.vector(1024);
create index if not exists novacart_knowledge_mistral_hnsw on public.novacart_knowledge using hnsw (embedding_mistral extensions.vector_cosine_ops);
create or replace function public.novacart_mistral_batch() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('entries',coalesce(jsonb_agg(jsonb_build_object('id',id,'text',title||': '||content) order by id),'[]')) from public.novacart_knowledge where active and embedding_mistral is null $$;
create or replace function public.novacart_mistral_save(p jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$ declare e jsonb; n integer:=0; begin for e in select value from jsonb_array_elements(p) loop update public.novacart_knowledge set embedding_mistral=(e->>'embedding')::extensions.vector(1024),embedding_model='mistral-embed' where id=e->>'id'; if found then n:=n+1; end if; end loop; return jsonb_build_object('updated',n); end $$;
create or replace function public.novacart_mistral_retrieve(query_embedding extensions.vector(1024)) returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('policies',coalesce(jsonb_agg(x),'[]'::jsonb),'retrieval_mode','semantic','embedding_model','mistral-embed') from (select k.id,k.title,k.content,1-(k.embedding_mistral operator(extensions.<=>) query_embedding) as similarity from public.novacart_knowledge k where k.active and k.embedding_mistral is not null and 1-(k.embedding_mistral operator(extensions.<=>) query_embedding)>0.15 order by k.embedding_mistral operator(extensions.<=>) query_embedding limit 8) x $$;
revoke all on function public.novacart_mistral_batch(), public.novacart_mistral_save(jsonb) from public,anon,authenticated;
grant execute on function public.novacart_mistral_batch(), public.novacart_mistral_save(jsonb) to service_role;
revoke all on function public.novacart_mistral_retrieve(extensions.vector) from public,anon;
grant execute on function public.novacart_mistral_retrieve(extensions.vector) to authenticated,service_role;